import {destinations,getDestination,announceDestination} from './destinations.js';
import {journeyAudio} from './soundscape.js';
const $=s=>document.querySelector(s);
const reduced=()=>window.zrMotionPaused||matchMedia('(prefers-reduced-motion: reduce)').matches;
const earthTexture=new THREE.TextureLoader().load('./assets/earth-atmosphere.jpg');earthTexture.colorSpace=THREE.SRGBColorSpace;
const geo=(lat,lon,r)=>{const p=(90-lat)*Math.PI/180,t=(lon+180)*Math.PI/180;return new THREE.Vector3(-r*Math.sin(p)*Math.cos(t),r*Math.cos(p),r*Math.sin(p)*Math.sin(t));};
const tidalWater=radius=>new THREE.Mesh(new THREE.SphereGeometry(radius,128,96),new THREE.ShaderMaterial({uniforms:{time:{value:0},earthMap:{value:earthTexture}},transparent:true,depthWrite:false,vertexShader:`uniform float time;varying vec2 uvMap;varying vec3 surface;varying vec3 normalView;varying float crest;void main(){vec3 n=normalize(position),moon=normalize(vec3(.25*sin(time*.18),1.,.18*cos(time*.18)));float a=dot(n,moon),bulge=.12*pow(max(a,0.),12.)+.035*pow(max(-a,0.),8.);float ripples=sin(n.x*35.+time*1.5+sin(n.z*19.-time))*.008+sin(n.y*53.-time*1.6+n.z*23.)*.005;vec3 p=n*(length(position)+bulge+ripples);uvMap=uv;crest=bulge;surface=(modelViewMatrix*vec4(p,1.)).xyz;normalView=normalize(normalMatrix*n);gl_Position=projectionMatrix*vec4(surface,1.);}`,fragmentShader:`uniform sampler2D earthMap;uniform float time;varying vec2 uvMap;varying vec3 surface;varying vec3 normalView;varying float crest;void main(){vec3 map=texture2D(earthMap,uvMap).rgb;float ocean=smoothstep(-.02,.12,map.b-map.r);vec3 v=normalize(-surface),l=normalize(vec3(-.5,.8,1.));float fres=pow(1.-max(dot(normalize(normalView),v),0.),4.);float current=.5+.5*sin(uvMap.y*160.+uvMap.x*90.+time*1.7)+.25*sin(uvMap.x*260.-time*1.2);float foam=smoothstep(.055,.12,crest)*pow(current,8.);vec3 water=mix(vec3(.005,.07,.12),vec3(.03,.42,.55),current*.52);water+=vec3(.32,.82,.86)*fres*.75;water=mix(water,vec3(.78,.9,.88),foam);gl_FragColor=vec4(water,ocean*(.18+fres*.45+foam*.55));}`}));
const pilot=$('#pilot');pilot.innerHTML='<canvas id="flightCanvas" aria-label="Interactive 3D helicopter route"></canvas><div class="flight-hud"><p class="eyebrow">ZR–02 / HELICOPTER JOURNEY</p><h2 id="flightHeading">Choose your next chapter.</h2><p id="flightRoute" aria-live="polite">Select any destination, then fly.</p><button id="closeFlight">Exit flight ×</button></div><div class="flight-flight-controls"><label for="flightDestination">Destination</label><select id="flightDestination"></select><button id="takeFlight">Fly / Enter →</button><button id="skipFlight">Skip animation →</button><button data-sound-toggle>Sound off</button></div><p class="flight-instructions">WASD / arrow keys to bank · Enter to travel · Escape to close</p><div class="jet-touch"><button data-jet="up" aria-label="Pitch up">↑</button><button data-jet="left" aria-label="Bank left">←</button><button data-jet="down" aria-label="Pitch down">↓</button><button data-jet="right" aria-label="Bank right">→</button></div>';
pilot.setAttribute('aria-labelledby','flightHeading');destinations.forEach(d=>$('#flightDestination').add(new Option(`${d.city} · ${d.country}`,d.city)));journeyAudio.bindControls();
let open=false,from='London',to='London',elapsed=0,flying=false,last=performance.now(),returnFocus=null,renderer=null,scene,camera,earth,plane,path,line,clouds,flightWater,flightTide=[],rotors=[];
const keys={left:false,right:false,up:false,down:false};
function setup(){if(renderer)return;renderer=new THREE.WebGLRenderer({canvas:$('#flightCanvas'),antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.toneMapping=THREE.ACESFilmicToneMapping;scene=new THREE.Scene();scene.background=new THREE.Color(0x06131e);scene.fog=new THREE.FogExp2(0x06131e,.012);camera=new THREE.PerspectiveCamera(45,1,.1,200);scene.add(new THREE.HemisphereLight(0xe6f5ff,0x345260,3));const sun=new THREE.DirectionalLight(0xffe1bd,4);sun.position.set(-15,15,12);scene.add(sun);earth=new THREE.Mesh(new THREE.SphereGeometry(9,96,72),new THREE.MeshStandardMaterial({map:earthTexture,roughness:.52,metalness:.08}));scene.add(earth);flightWater=tidalWater(9.11);scene.add(flightWater);const helicopter=makeHelicopter(scene,.62);plane=helicopter.heli;rotors=[helicopter.rotor,helicopter.tailRotor];clouds=new THREE.Group();scene.add(clouds);const cloudMat=new THREE.MeshBasicMaterial({color:0xc8e5ee,transparent:true,opacity:.045,depthWrite:false});for(let i=0;i<24;i++){const c=new THREE.Mesh(new THREE.SphereGeometry(.8,8,6),cloudMat);c.position.copy(geo((i*37)%130-65,i*57%360-180,11.8));c.scale.set(2.5,.45,1);clouds.add(c);}}
function openPilot(){if(open)return;returnFocus=document.activeElement;open=true;pilot.classList.add('is-open');pilot.setAttribute('aria-hidden','false');document.body.classList.add('pilot-open');$('#closeFlight').focus();try{setup();}catch{renderer=null;$('#flightRoute').textContent='3D unavailable here. Choose a destination to open its story.';}journeyAudio.mix();}
function closePilot(){open=false;flying=false;Object.keys(keys).forEach(k=>keys[k]=false);pilot.classList.remove('is-open');pilot.setAttribute('aria-hidden','true');document.body.classList.remove('pilot-open');returnFocus?.focus({preventScroll:true});journeyAudio.mix();}
function arrive(){const destination=to;from=destination;closePilot();window.zrOpenCity?.(destination);window.zrSelectDestination?.(destination);announceDestination(destination);journeyAudio.play('city-arrival',.45);}
function fly(city,origin=from){const d=getDestination(city),start=getDestination(origin)||destinations[0];if(!d)return;to=d.city;$('#flightDestination').value=to;openPilot();$('#flightHeading').textContent=d.city;$('#flightRoute').textContent=`${start.city} → ${d.city} · ${d.country}`;if(reduced()||!renderer){arrive();return;}const a=geo(start.lat,start.lon,9.7),b=geo(d.lat,d.lon,9.7),points=[];for(let i=0;i<=60;i++){const t=i/60;let v=a.clone().lerp(b,t);if(v.length()<.1)v=a.clone();v.normalize().multiplyScalar(9.7+Math.sin(t*Math.PI)*3.5);points.push(v);}path=new THREE.CatmullRomCurve3(points);if(line){scene.remove(line);line.geometry.dispose();line.material.dispose();}line=new THREE.Line(new THREE.BufferGeometry().setFromPoints(path.getPoints(100)),new THREE.LineBasicMaterial({color:0xf0c989,transparent:true,opacity:.7}));scene.add(line);elapsed=0;flying=true;journeyAudio.play('jet-flyby',.5);}
window.zrFlyTo=fly;$('#launchPilot').onclick=()=>{to=$('#flightDestination').value;openPilot();};$('#closeFlight').onclick=closePilot;$('#takeFlight').onclick=()=>fly($('#flightDestination').value);$('#skipFlight').onclick=()=>{to=$('#flightDestination').value;arrive();};
const keyMap={ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right',ArrowUp:'up',KeyW:'up',ArrowDown:'down',KeyS:'down'};
addEventListener('keydown',e=>{if(!open)return;if(e.code==='Escape'){e.preventDefault();closePilot();return;}if(e.code==='Tab'){const focusable=[...pilot.querySelectorAll('button,select')];const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}return;}if(e.target.closest('select'))return;if(keyMap[e.code]){e.preventDefault();keys[keyMap[e.code]]=true;}if(e.code==='Enter'&&!e.target.closest('button')){e.preventDefault();if(flying)arrive();else fly($('#flightDestination').value);}});addEventListener('keyup',e=>{if(keyMap[e.code])keys[keyMap[e.code]]=false;});addEventListener('blur',()=>Object.keys(keys).forEach(k=>keys[k]=false));
pilot.querySelectorAll('[data-jet]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys[b.dataset.jet]=true;};b.onpointerup=b.onpointercancel=()=>keys[b.dataset.jet]=false;});
function animate(now){requestAnimationFrame(animate);const dt=Math.min(.04,(now-last)/1000);last=now;if(!open||!renderer||document.hidden)return;const canvas=$('#flightCanvas'),w=canvas.clientWidth,h=canvas.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();if(flying){elapsed+=dt;const t=Math.min(elapsed/3.8,1),p=path.getPoint(t);plane.position.copy(p);const tangent=path.getTangent(Math.min(t,.999));plane.up.copy(p.clone().normalize());plane.lookAt(p.clone().add(tangent));plane.rotateY(Math.PI);plane.rotateZ((keys.left?.35:0)-(keys.right?.35:0)+Math.sin(t*Math.PI*2)*.16);plane.rotateX((keys.up?.2:0)-(keys.down?.2:0));const target=p.clone().normalize().multiplyScalar(innerWidth<760?26:23).add(new THREE.Vector3(4,3,4));camera.position.lerp(target,Math.min(1,dt*3));camera.lookAt(p.clone().multiplyScalar(.6));if(t>=1){arrive();return;}}else{const t=now*.00012;plane.position.set(Math.sin(t)*12,4,Math.cos(t)*12);plane.rotation.set((keys.up?.2:0)-(keys.down?.2:0),t+Math.PI/2,(keys.left?.35:0)-(keys.right?.35:0)-.12);camera.position.set(12,12,innerWidth<760?35:26);camera.lookAt(0,0,0);if(!reduced()){earth.rotation.y+=dt*.018;flightWater.rotation.y=earth.rotation.y;flightWater.material.uniforms.time.value=now*.001;}}if(!reduced())clouds.rotation.y+=dt*.015;rotors.forEach((rotor,i)=>rotor.rotation[i?'z':'y']+=dt*(i?28:38));renderer.render(scene,camera);}
requestAnimationFrame(animate);

// Replace the abstract dotted map with a textured earth; retain the accessible city buttons.
try{
 const old=$('#globeCanvas'),canvas=document.createElement('canvas');canvas.id='globeCanvas3D';canvas.setAttribute('aria-label','Earth with clickable city markers. Use the destination buttons for keyboard access.');old.hidden=true;old.after(canvas);
 const r=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true});r.setPixelRatio(Math.min(devicePixelRatio,1.8));const s=new THREE.Scene(),cam=new THREE.PerspectiveCamera(40,1,.1,100);cam.position.set(0,0,16);s.add(new THREE.HemisphereLight(0xffffff,0x254653,2.5));const light=new THREE.DirectionalLight(0xffecc8,3);light.position.set(-6,6,10);s.add(light);const group=new THREE.Group();s.add(group);const globe=new THREE.Mesh(new THREE.SphereGeometry(4.5,96,72),new THREE.MeshStandardMaterial({map:earthTexture,roughness:.52,metalness:.08}));group.add(globe);const water=tidalWater(4.61);group.add(water);
 const markers=[];destinations.forEach(d=>{const m=new THREE.Mesh(new THREE.SphereGeometry(.07,10,8),new THREE.MeshBasicMaterial({color:0xf7d68d}));m.position.copy(geo(d.lat,d.lon,4.58));m.userData.city=d.city;group.add(m);markers.push(m);});
 let rotation=0,target=0,auto=true,drag=false,lastX=0,startX=0,lastTime=performance.now();const ray=new THREE.Raycaster();canvas.style.touchAction='pan-y';canvas.onpointerdown=e=>{drag=true;auto=false;startX=lastX=e.clientX;canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(drag){target+=(e.clientX-lastX)*.008;lastX=e.clientX;}};canvas.onpointerup=e=>{drag=false;if(Math.abs(e.clientX-startX)>8)return;const rect=canvas.getBoundingClientRect();ray.setFromCamera(new THREE.Vector2((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1),cam);const hit=ray.intersectObjects([globe,...markers]);if(hit[0]?.object.userData.city)fly(hit[0].object.userData.city);};canvas.onpointercancel=()=>drag=false;$('#globeReset').addEventListener('click',()=>auto=true);
 window.addEventListener('zr:destination',e=>{auto=false;target=-(e.detail.lon+90)*Math.PI/180;});
 function render(now){requestAnimationFrame(render);const dt=Math.min(.04,(now-lastTime)/1000);lastTime=now;const rect=canvas.getBoundingClientRect();if(rect.bottom<0||rect.top>innerHeight||document.hidden)return;r.setSize(rect.width,rect.height,false);cam.aspect=rect.width/rect.height;cam.updateProjectionMatrix();if(auto&&!reduced())target+=dt*.08;rotation=THREE.MathUtils.lerp(rotation,target,.08);group.rotation.y=rotation;if(!reduced())water.material.uniforms.time.value=now*.001;r.render(s,cam);}requestAnimationFrame(render);
}catch(error){$('#globeCanvas').hidden=false;$('#globeCanvas3D')?.remove();}
